const html_raw = $json.styled_html || '';
let data = Array.isArray($json.data) ? $json.data : [];
const groupByField = $json.group_by;
const schema = $json.schema || ($('When Called by Another Workflow').first().json.schema);
const isInsertMode = data.length === 0 && html_raw.includes('<form');
if (isInsertMode) { data = [{}]; }
const selectTokenRegex = /\{\{\{([a-zA-Z0-9_]+):([a-zA-Z0-9_]+)\}\}\}/g;
const selectConfigs = [];
let m;
while ((m = selectTokenRegex.exec(html_raw)) !== null) {
  selectConfigs.push({ templateName: m[1], fieldName: m[2], fullToken: m[0] });
}
const base = { html_raw, data, groupByField, isInsertMode, schema };
if (selectConfigs.length > 0 && data.length > 0) {
  const record = data[0];
  return selectConfigs.map(cfg => {
    const baseTemplateName = cfg.templateName.startsWith('f_') ? cfg.templateName.slice(2) : cfg.templateName;
    return { json: { ...base, fullToken: cfg.fullToken, templateName: baseTemplateName, fieldName: cfg.fieldName, currentVal: record[cfg.fieldName] || 0 } };
  });
}
return [{ json: { ...base, fullToken: '__NONE__', templateName: '__NONE__', fieldName: '__NONE__', currentVal: 0 } }];

const items = $input.all();
const first = $('L03a - detect tokens').first().json;
const data = Array.isArray(first.data) ? first.data : [];
const groupByField = first.groupByField;
let html = first.html_raw || '';
for (const item of items) {
  const fullToken = item.json.full_token;
  if (fullToken && fullToken !== '__NONE__') {
    const selectHtml = (!item.json.error && item.json.html) ? item.json.html : '';
    html = html.split(fullToken).join(selectHtml);
  }
}
const applyRow = (tpl, row) => {
  let out = tpl;
  for (const [key, value] of Object.entries(row)) {
    const safeVal = String(value ?? '');
    out = out.split('{{{' + key + '}}}').join(safeVal);
    out = out.split('{{' + key + '}}').join(safeVal);
  }
  return out;
};
const eachRegex = /\{\{#each data\}\}([\s\S]*?)\{\{\/each\}\}/;
const match = html.match(eachRegex);
if (match) {
  const rowTemplate = match[1];
  const rows = data.map((item, index) => {
    let row = '';
    if (groupByField && (index === 0 || item[groupByField] !== data[index-1][groupByField])) {
      row += '<tr class="group-hdr"><td colspan="99"><strong>' + String(item[groupByField] ?? '') + '</strong></td></tr>';
    }
    const slotRegex = /\{\{slot:[^\}]+\}\}/g;
    const slots = [];
    let slotIndex = 0;
    let chunk = rowTemplate.replace(slotRegex, (mm) => { slots.push(mm); return '___SLOT_PH_' + (slotIndex++) + '___'; });
    chunk = applyRow(chunk, item);
    for (let i = 0; i < slots.length; i++) { chunk = chunk.split('___SLOT_PH_' + i + '___').join(slots[i]); }
    chunk = chunk.replace(/\{\{#if\s+(\w+)\}\}([\s\S]*?)\{\{\/if\}\}/g, (mm, cond, content) => item[cond] ? content : '');
    return row + chunk;
  }).join('');
  html = html.replace(eachRegex, () => rows);
} else if (data.length > 0) {
  html = applyRow(html, data[0]);
}
return [{ json: { html, isInsertMode: first.isInsertMode } }];

let html = $json.html || '';
const isInsertMode = $json.isInsertMode || false;
if (isInsertMode) {
  const slotRegex = /\{\{slot:[^\}]+\}\}/g;
  const slots = [];
  let idx = 0;
  html = html.replace(slotRegex, (m) => { slots.push(m); return '___SLOT_PH_' + (idx++) + '___'; });
  html = html.replace(/\{\{\{[a-zA-Z0-9_]+\}\}\}/g, '');
  html = html.replace(/\{\{[a-zA-Z0-9_]+\}\}/g, '');
  for (let i = 0; i < slots.length; i++) { html = html.split('___SLOT_PH_' + i + '___').join(slots[i]); }
}
return [{ json: { html } }];
